import{_ as r,o,c as s,a2 as a}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"全景对照表","description":"","frontmatter":{},"headers":[],"relativePath":"tools/landscape.md","filePath":"tools/landscape.md","lastUpdated":1786503105000}'),d={name:"tools/landscape.md"};function n(l,t,e,i,g,p){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="全景对照表" tabindex="-1">全景对照表 <a class="header-anchor" href="#全景对照表" aria-label="Permalink to &quot;全景对照表&quot;">​</a></h1><p>做一支广告，链路上有五类工具。先搞清楚每一类负责什么，再决定具体用哪个。</p><div class="warning custom-block"><p class="custom-block-title">本页只写定位，不写参数</p><p>价格、时长上限、分辨率、功能开关等信息变化极快，一律不写。<strong>具体能力请以各家官网和你自己的实测为准。</strong></p></div><h2 id="五类工具的位置" tabindex="-1">五类工具的位置 <a class="header-anchor" href="#五类工具的位置" aria-label="Permalink to &quot;五类工具的位置&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 文案与策略  →  ② 图像生成  →  ③ 视频生成  →  ④ 配音与音乐  →  ⑤ 剪辑与后期</span></span>
<span class="line"><span>   想什么          画出来         动起来          听得见          串成片</span></span></code></pre></div><p>对应 <a href="/method/workflow-sop">完整链路 SOP</a> 的六个阶段：①覆盖阶段 1–4，②③覆盖阶段 5，④⑤覆盖阶段 6。</p><hr><h2 id="_1-文案与策略" tabindex="-1">① 文案与策略 <a class="header-anchor" href="#_1-文案与策略" aria-label="Permalink to &quot;① 文案与策略&quot;">​</a></h2><p><strong>这一类干什么</strong>：拆 brief、找洞察、写分镜表、写 slogan 和口播稿。</p><p><strong>主流选项</strong>：Claude、ChatGPT、Gemini，以及国内的通义、豆包、Kimi 等。</p><p><strong>选择要点</strong></p><table tabindex="0"><thead><tr><th>关注点</th><th>说明</th></tr></thead><tbody><tr><td>长文本处理</td><td>要把整份 brief、产品资料、竞品分析一起丢进去，上下文窗口越大越省事</td></tr><tr><td>中文语感</td><td>广告文案对语感要求高。这一项建议自己拿同一个 Prompt 横向试一遍，感受差异明显</td></tr><tr><td>指令遵循</td><td><a href="/prompts/copywriting">文案 Prompt</a> 里那些约束条款（字数、禁用词、输出格式），模型能不能老实执行，差别很大</td></tr></tbody></table><p><strong>经验判断</strong>：这一类的选择其实不太关键，主流模型都够用。<strong>决定产出质量的是你的 Prompt 约束写得够不够狠</strong>，不是选了哪家。</p><hr><h2 id="_2-图像生成" tabindex="-1">② 图像生成 <a class="header-anchor" href="#_2-图像生成" aria-label="Permalink to &quot;② 图像生成&quot;">​</a></h2><p><strong>这一类干什么</strong>：主图、KV、海报、概念图，以及视频的首帧参考图。</p><p><strong>按能力分成三种类型</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>擅长</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>通用生成型</strong></td><td>从文字直接出图，风格多样，创意发散</td><td>概念视觉、氛围图、故事板草图</td></tr><tr><td><strong>图像编辑型</strong></td><td>基于已有图片修改（换背景、去物体、扩图、局部重绘）</td><td>产品图精修、批量换背景</td></tr><tr><td><strong>参考控制型</strong></td><td>用参考图约束构图、姿态、人物外观</td><td>一致性要求高的系列图</td></tr></tbody></table><p>代表性产品：Midjourney、Stable Diffusion 生态、DALL·E、Firefly，以及国内的即梦、可灵、通义万相等。多数产品同时具备上面两三种能力，边界在模糊。</p><p><strong>选择要点</strong></p><ul><li><strong>商用授权</strong>是第一位的。不同产品对生成内容的商用条款差异很大，有的与订阅档位挂钩。<strong>签合同前务必确认清楚</strong>，这是最容易出事的地方。</li><li><strong>可控性 vs 出图上限</strong>。有些工具出图惊艳但难以精确控制，有些平淡但改起来听话。做品牌项目要可控性，做概念探索要上限。</li><li><strong>中文场景理解</strong>。做本土化内容（中式场景、亚洲面孔、中文环境）时，国内模型往往更贴合。</li></ul><p><strong>共同的短板</strong></p><div class="warning custom-block"><p class="custom-block-title">三件事目前所有图像工具都做不好</p><ol><li><strong>精确复现一个真实存在的产品</strong>。有 logo、有特定造型的产品，纯生成基本不可能准确。务实做法：AI 生成背景与光环境，产品用实拍图合成。</li><li><strong>生成可用的中文文字</strong>。生成出来的&quot;文字&quot;绝大多数是乱码或错字。<strong>海报上的所有文字都应该在后期用设计软件加。</strong></li><li><strong>手部和复杂肢体</strong>。改善很多但仍是高频问题，出图后必查。</li></ol></div><hr><h2 id="_3-视频生成" tabindex="-1">③ 视频生成 <a class="header-anchor" href="#_3-视频生成" aria-label="Permalink to &quot;③ 视频生成&quot;">​</a></h2><p><strong>这一类干什么</strong>：把分镜表变成动态素材。</p><p><strong>按输入方式分成三种</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>输入</th><th>特点</th></tr></thead><tbody><tr><td><strong>文生视频</strong></td><td>文字</td><td>自由度高，可控性低</td></tr><tr><td><strong>图生视频</strong></td><td>一张图 + 动作描述</td><td>**实际工作中用得最多。**先用图像模型把画面调满意，再让它动起来，可控性高得多</td></tr><tr><td><strong>首尾帧</strong></td><td>起始图 + 结束图</td><td>控制力最强，适合有明确变化过程的镜头</td></tr></tbody></table><p>代表性产品：Sora、Runway、可灵、即梦、海螺、Pika、Luma 等。</p><p><strong>选择要点</strong></p><ul><li><strong>动态自然度</strong>：人物动作、液体流动、织物飘动是否符合物理直觉。这是最能拉开差距的一项。</li><li><strong>提示词服从度</strong>：写了&quot;缓慢推近&quot;，它是否真的推近。</li><li><strong>一致性能力</strong>：是否支持参考图锚定人物/产品。</li><li><strong>生成速度与成本</strong>：视频废片率高，单次成本和等待时间会显著影响实际工作节奏。</li></ul><div class="warning custom-block"><p class="custom-block-title">所有视频工具当前的共同边界</p><ul><li><strong>快速运动会导致畸变</strong>。这是结构性的，所有工具都有，只是程度不同。Prompt 里主动写&quot;缓慢地&quot;是必要的对策。</li><li><strong>复杂运镜不可靠</strong>。一个镜头一个运镜。</li><li><strong>时长不精确</strong>。别指望它精确给你 2.5 秒，多生成、剪辑时裁。</li><li><strong>口型同步</strong>。有口播时对不上是常态，画外音是更稳的解法。</li></ul></div><hr><h2 id="_4-配音与音乐" tabindex="-1">④ 配音与音乐 <a class="header-anchor" href="#_4-配音与音乐" aria-label="Permalink to &quot;④ 配音与音乐&quot;">​</a></h2><p><strong>这一类干什么</strong>：口播、旁白、配乐、音效。</p><table tabindex="0"><thead><tr><th>子类</th><th>说明</th></tr></thead><tbody><tr><td><strong>语音合成（TTS）</strong></td><td>中文自然度已经很够用，多数广告口播可以直接用。代表：ElevenLabs、火山引擎语音、微软 Azure TTS 等</td></tr><tr><td><strong>音乐生成</strong></td><td>Suno、Udio 等。做背景音乐够用，<strong>但商用授权条款务必逐条确认</strong></td></tr><tr><td><strong>音效</strong></td><td>需求量小，多数情况下用音效素材库比生成更快更准</td></tr></tbody></table><p><strong>配音的实操要点</strong></p><ul><li><strong>手动断句</strong>。在需要停顿的地方加逗号或换行，比让模型自己判断可靠得多。</li><li><strong>语速要慢一点</strong>。生成的语音听起来常比预想的快，可以适当调慢。</li><li><strong>情绪不要给太满</strong>。TTS 的&quot;高兴&quot;&quot;激动&quot;容易过头，平静的语气反而更可信。</li></ul><div class="danger custom-block"><p class="custom-block-title">声音克隆的红线</p><p>克隆真实人物的声音用于商业广告，必须持有该人物的明确书面授权。未经授权的声音克隆同样构成侵权。参见 <a href="/prompts/spokesperson">人物代言</a>。</p></div><hr><h2 id="_5-剪辑与后期" tabindex="-1">⑤ 剪辑与后期 <a class="header-anchor" href="#_5-剪辑与后期" aria-label="Permalink to &quot;⑤ 剪辑与后期&quot;">​</a></h2><p><strong>这一类干什么</strong>：把素材串成片，调色、加字幕、导出。</p><p><strong>现状判断</strong>：AI 在这一层的成熟度<strong>低于</strong>前面几层。带 AI 功能的剪辑工具（自动剪辑、自动字幕、自动配乐）能省一些体力活，但<strong>成片的节奏和调色仍然靠人</strong>。</p><p>实际工作中，这一步用传统软件（剪映、Premiere、达芬奇、Final Cut）比用 AI 工具更快。</p><p><strong>这一步真正的价值</strong>：把一堆&quot;还行&quot;的 AI 素材，通过节奏和统一调色，变成一支&quot;完整&quot;的片子。</p><div class="tip custom-block"><p class="custom-block-title">调色是 AI 素材的救命稻草</p><p>AI 生成的素材普遍存在色温漂移——每个镜头的色调都不太一样。**全片套同一个 LUT，能救回相当一部分风格不统一的问题。**这一招的性价比远高于回去重新生成。</p></div><hr><h2 id="一张总表" tabindex="-1">一张总表 <a class="header-anchor" href="#一张总表" aria-label="Permalink to &quot;一张总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>成熟度</th><th>人的介入程度</th><th>主要风险</th></tr></thead><tbody><tr><td>① 文案与策略</td><td>高</td><td>高（判断）</td><td>产出平均值、合规踩线</td></tr><tr><td>② 图像生成</td><td>高</td><td>中（筛选）</td><td>产品失真、商用授权</td></tr><tr><td>③ 视频生成</td><td>中</td><td>中（筛选）</td><td>动作畸变、一致性</td></tr><tr><td>④ 配音与音乐</td><td>高</td><td>低</td><td>商用授权、声音侵权</td></tr><tr><td>⑤ 剪辑与后期</td><td>低</td><td>高（执行）</td><td>——</td></tr></tbody></table><p><strong>读法</strong>：成熟度高、人介入低的环节（配音），放心交给 AI；成熟度低、人介入高的环节（剪辑），别指望 AI，老老实实自己做。</p><h2 id="接着看" tabindex="-1">接着看 <a class="header-anchor" href="#接着看" aria-label="Permalink to &quot;接着看&quot;">​</a></h2><ul><li>具体该选哪套 → <a href="/tools/decision-tree">选型决策树</a></li><li>工具怎么用 → <a href="/prompts/structure">Prompt 结构通法</a></li></ul>`,52)])])}const u=r(d,[["render",n]]);export{c as __pageData,u as default};
